const scanOfflineClients = `-- name: ScanOfflineClients :many
SELECT c.id AS client_id, c.org_id, c.name AS client_name, c.last_seen
FROM clients c
WHERE c.status = 'active' AND c.last_seen IS NOT NULL
  AND c.last_seen < $1::timestamptz AND c.last_seen >= $2::timestamptz
  AND EXISTS (SELECT 1 FROM client_cert_grants g WHERE g.client_id = c.id AND g.removed_at IS NULL)
  AND NOT EXISTS (
    SELECT 1 FROM notification_events e
    WHERE e.dedupe_key = 'client.offline:' || c.id::text || ':' || extract(epoch FROM c.last_seen)::bigint::text
  )
ORDER BY c.last_seen, c.id
LIMIT $3::int
`

type ScanOfflineClientsParams struct {
	Cutoff    time.Time `json:"cutoff"`
	Since     time.Time `json:"since"`
	PageLimit int32     `json:"page_limit"`
}

type ScanOfflineClientsRow struct {
	ClientID   uuid.UUID  `json:"client_id"`
	OrgID      uuid.UUID  `json:"org_id"`
	ClientName string     `json:"client_name"`
	LastSeen   *time.Time `json:"last_seen"`
}

// client.offline (task-7 brief): an active client last seen before cutoff,
// with at least one live grant (removed_at IS NULL) — a client with
// nothing deployed to it never alerts. last_seen IS NOT NULL excludes a
// client that has never connected at all (enrolled but not yet activated
// by its first heartbeat). The dedupe key is keyed on last_seen itself, so
// a client that reconnects and later goes offline again is a fresh
// condition (a new last_seen value never seen in dedupe_key before).
// last_seen >= since: same prune-window reasoning as
// ScanExpiredCertificateVersions — otherwise a client offline for over
// EventRetention re-emits once its dedupe row is pruned.
func (q *Queries) ScanOfflineClients(ctx context.Context, arg ScanOfflineClientsParams) ([]ScanOfflineClientsRow, error) {
	rows, err := q.db.Query(ctx, scanOfflineClients, arg.Cutoff, arg.Since, arg.PageLimit)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ScanOfflineClientsRow{}
	for rows.Next() {
		var i ScanOfflineClientsRow
		if err := rows.Scan(
			&i.ClientID,
			&i.OrgID,
			&i.ClientName,
			&i.LastSeen,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const updateNotificationChannel = `-- name: UpdateNotificationChannel :one
UPDATE notification_channels SET name = $1, config = $2, secret_cfg = $3,
       stored_secret_keys = COALESCE($4::text[], '{}'),
       events = $5, min_severity = $6, all_orgs = $7,
       enabled = $8, updated_at = now()
WHERE id = $9 AND org_id = $10 RETURNING id, org_id, name, type, config, secret_cfg, events, min_severity, all_orgs, enabled, created_at, updated_at, stored_secret_keys
`

type UpdateNotificationChannelParams struct {
	Name             string    `json:"name"`
	Config           []byte    `json:"config"`
	SecretCfg        []byte    `json:"secret_cfg"`
	StoredSecretKeys []string  `json:"stored_secret_keys"`
	Events           []string  `json:"events"`
	MinSeverity      string    `json:"min_severity"`
	AllOrgs          bool      `json:"all_orgs"`
	Enabled          bool      `json:"enabled"`
	ID               uuid.UUID `json:"id"`
	OrgID            uuid.UUID `json:"org_id"`
}

func (q *Queries) UpdateNotificationChannel(ctx context.Context, arg UpdateNotificationChannelParams) (NotificationChannel, error) {
	row := q.db.QueryRow(ctx, updateNotificationChannel,
		arg.Name,
		arg.Config,
		arg.SecretCfg,
		arg.StoredSecretKeys,
		arg.Events,
		arg.MinSeverity,
		arg.AllOrgs,
		arg.Enabled,
		arg.ID,
		arg.OrgID,
	)
	var i NotificationChannel
	err := row.Scan(
		&i.ID,
		&i.OrgID,
		&i.Name,
		&i.Type,
		&i.Config,
		&i.SecretCfg,
		&i.Events,
		&i.MinSeverity,
		&i.AllOrgs,
		&i.Enabled,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.StoredSecretKeys,
	)
	return i, err
}
